// TH14 源 type -> 目标弹型常量（transcribe/th14/touhou-bullets.ecl）
// 本卡只用到以下四种：源 etSprite type 38/39/40/42。

const TH14_NOTE_RED: int = 976;    // 源 type 38
const TH14_NOTE_BLUE: int = 992;   // 源 type 39
const TH14_NOTE_YELLOW: int = 1008; // 源 type 40
const TH14_REST: int = 1040;       // 源 type 42

// th14_s7_b17 — TH14 v1.00b Extra 关底 Boss9 → BossCard9（spellEx 118「ブルーレディショー」）
// 源: st07bs.ecl.txt:913-951 Boss9 入口 / 2129-2183 BossCard9
//     2185-2239 BossCard9_at / 2241-2315 at2 / 2317-2421 at3
//     2423-2476 beat1/2/3；弹型映射见 bullets.ecl。
//
// 源时间轴（从 BossCard9 的 timerReset 起算，单位帧）：
//   t=60 表现段；t=150 标签 + wait(18)；t=168 call at1（1200帧）
//   t=1368 + wait(120) = 1488 call at2（1200帧）
//   t=2688 + wait(120) = 2808 call at3（源 $B=4800，在 t=4500 原生超时处截断）
// 截断后 at3 实际执行 4500-2808 = 1692 帧；外壳时限留出 wrapper 与尾弹余量。

const TIME_LIMIT: int = 5044;   // 120 外壳开场 + 120 wrapper + 4500 原生 + 300 尾弹 + 4 启动余量
const OPENING_BUFFER: int = 120;

const CARD9_LEAD: int = 168;    // 源 BossCard9 到 at1 的固定前奏
const PHASE_GAP: int = 120;     // at1/at2 之后的 wait(120)
const AT3_LEN: int = 1692;      // 4800 被 4500 原生时限截断
const BEAT_PERIOD: int = 46;    // beat1/2/3 的 wait(46)

// 外壳：control 只承载段事件；真实 Boss 在开场缓冲后按源位置生成。
sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 4000, 0, 0, 0, boss9);
}

// 源 Boss9:913-951。清场/符卡声明/funcSet/laserCancel/旧弹取消在独立场景无对象，省略；
// 内部 LIFE 4000 由生成参数承载；movePosTime(60,4,0,128) 的终点即生成位置，限位不再生效。
async sub boss9() {
    set_invuln(65535);
    set_hitbox(24fx);   // 源 Boss() context_only:27-28 setHurtbox/SetHitbox(48,48) -> 半径×0.5
    set_hurtbox(24fx);
    wait(120);          // 源 Boss9:948
    boss_card9();       // 源 Boss9:949
    loop { wait(600); }
}

sub boss_card9() {
    // 源 BossCard9:2133 timerReset；setInterrupt(0,0,4500,"Boss10") 的原生时限
    // 由 at3 的截断帧数与外壳时限分别承载，不启动 Boss10。
    wait(CARD9_LEAD);
    at1();
    wait(PHASE_GAP);
    at2();
    wait(PHASE_GAP);
    at3();
}

// ---- at1: 源 BossCard9_at:2188-2238 ----
// 4 个 8 路固定环（aim=3）；beat 在绝对发射位 (-184,0)/(-184,448)/(184,...) 上开火。
sub at1() {
    set_self_int(0, 1);    // $GI0
    set_self_fx(0, 0fx);   // %A（以 BAM 计的旋转量）
    spawn beat_ring(0, -184fx, 1, TH14_NOTE_RED, 0, 2.0fx);      // emitter 0
    spawn beat_ring(207, 184fx, -1, TH14_NOTE_BLUE, 0, 2.0fx);   // emitter 1
    spawn beat_ring(402, -184fx, 1, TH14_NOTE_YELLOW, 0, 2.0fx); // emitter 2
    spawn beat_ring(563, 184fx, -1, TH14_NOTE_YELLOW, 0, 2.0fx); // emitter 3
    for k in 0..1200 {
        wait(1);
        set_self_fx(0, self_fx(0) + 15.8333fx);  // 源 %A += 0.001518 rad/帧
    }
    set_self_int(0, 0);    // 源 at 段结束置 $GI0=0，不 kill 正在 wait 的 async
}

// ---- at2: 源 BossCard9_at2:2244-2314 ----
sub at2() {
    set_self_int(0, 1);
    set_self_fx(0, 0fx);
    spawn beat_ring(0, -184fx, 1, TH14_NOTE_RED, 0, 2.5fx);      // emitter 0
    spawn beat_ring(23, 184fx, -1, TH14_NOTE_BLUE, 0, 2.5fx);    // emitter 1
    spawn beat_ring(218, -184fx, 1, TH14_NOTE_YELLOW, 0, 2.5fx); // emitter 2
    spawn beat_ring(195, 184fx, -1, TH14_NOTE_YELLOW, 0, 2.5fx); // emitter 3
    spawn beat_ring(384, -184fx, 1, TH14_NOTE_YELLOW, 0, 2.5fx); // emitter 4
    spawn beat_ring(407, 184fx, -1, TH14_NOTE_YELLOW, 0, 2.5fx); // emitter 5
    for k in 0..1200 {
        wait(1);
        set_self_fx(0, self_fx(0) - 23.75fx);    // 源 %A -= 0.002277 rad/帧
    }
    set_self_int(0, 0);
}

// ---- at3: 源 BossCard9_at3:2320-2420 ----
// 8 个 8 路固定环 + emitter 6：20 路自机狙环（源 type 42 休符、color 3、速度 1.2），
// 从 Boss 位置（无 etOffset）由 beat3 开火。
sub at3() {
    set_self_int(0, 1);
    set_self_fx(0, 0fx);
    spawn beat_ring(0, -184fx, 1, TH14_NOTE_RED, 0, 2.3fx);      // emitter 0
    spawn beat_ring(23, 184fx, -1, TH14_NOTE_BLUE, 0, 2.3fx);    // emitter 1
    spawn beat_ring(218, -184fx, 1, TH14_NOTE_YELLOW, 0, 2.3fx); // emitter 2
    spawn beat_ring(195, 184fx, -1, TH14_NOTE_YELLOW, 0, 2.3fx); // emitter 3
    spawn beat_ring(384, -184fx, 1, TH14_NOTE_YELLOW, 0, 2.3fx); // emitter 4
    spawn beat_ring(407, -184fx, 1, TH14_NOTE_YELLOW, 0, 2.3fx); // emitter 5（beat1/ -90°）
    spawn beat_ring(588, 184fx, -1, TH14_NOTE_BLUE, 0, 2.3fx);   // emitter 7
    spawn beat_ring(570, 184fx, -1, TH14_NOTE_BLUE, 0, 2.3fx);   // emitter 8
    spawn beat_rest(552);                                        // emitter 6（beat3）
    for k in 0..AT3_LEN {
        wait(1);
        set_self_fx(0, self_fx(0) - 23.75fx);
    }
    set_self_int(0, 0);
}

// 源 beat1/beat2:2423-2461：wait(delay) 后每 46 帧在 side 的上下两条边各开一次 8 路环。
// dir=+1 对应源 etAngle 的 1.5707964-A，dir=-1 对应 -1.5707964-A。
async sub beat_ring(delay: int, side: fx, dir: int, shape: int, color: int, speed: fx) {
    wait(delay);
    while self_int(0) == 1 {
        var base: angle = (dir * 16384 - (self_fx(0) as int)) as angle;
        fire_ring(side, 0fx, base, shape, color, speed, 8, 0);
        fire_ring(side, 448fx, base, shape, color, speed, 8, 0);
        wait(BEAT_PERIOD);
    }
}

// 源 beat3:2463-2475：只 etOn，无 offset，弹从 Boss 位置出生。
async sub beat_rest(delay: int) {
    wait(delay);
    while self_int(0) == 1 {
        var base: angle = (16384 - (self_fx(0) as int)) as angle;
        fire_ring($self_x, $self_y, base, TH14_REST, 3, 1.2fx, 20, 1);
        wait(BEAT_PERIOD);
    }
}

// 一波 etOn：固定环（aimed=0）或自机狙环（aimed=1，整波只取一次自机角）。
// 源 EX 槽 0 的出生 ANIM 退位移保留：出生点沿弹角后退 4×初速。
sub fire_ring(x: fx, y: fx, base: angle, shape: int, color: int, speed: fx, ways: int, aimed: int) {
    var aim: angle = 0deg;
    if aimed != 0 { aim = aim_player(); }
    for i in 0..ways {
        var a: angle = base + aim + (((i * 65536) / ways) as angle);
        _ = fire(shape, color,
                 x - 4fx * speed * cos(a),
                 y - 4fx * speed * sin(a),
                 speed, a, none, none);
    }
}
